const SHARED_USER = 'qa@shop.test';

test('update display name', async ({ page }) => {
  await loginAs(page, SHARED_USER);
  await page.goto('/profile');
  await page.getByLabel('Display name').fill('Tester A');
  await page.getByRole('button', { name: 'Save' }).click();
  await expect(page.getByTestId('display-name')).toHaveText('Tester A');
});

test('reset display name', async ({ page }) => {
